mapper.select:
SELECT A.FINPROD_ID FINPROD_ID,/**金融产品代码**/ A.FINPROD_ABBR FINPROD_ABBR,/**金融产品简称**/ A.FINPROD_MARKET_ID FINPROD_MARKET_ID,/**市场代码**/ A.VDATE VDATE,/**起息日**/ A.MDATE MDATE,/**到期日**/ A.ISSUE_PRICE ISSUE_PRICE,/**发行价**/ D.TYPE_18 AS SEC_TYPE,/**证券品种**/ D.TYPE_1 AS SEC_TYPE_DETAIL /**证券细分类**/ FROM FIN_PRODUCT A /**标的类金融产品表**/ INNER JOIN FIN_PRODUCT_TYPE D ON A.FINPROD_ID = D.FINPROD_ID/**金融产品分类表**/ WHERE 1 = 1 AND D.TYPE_18 = '01' AND (D.TYPE_1 = '033' OR (A.IS_SUS = '01' AND A.IS_RIGHT = '02'))/**优先股、不含权的永续债**/ AND ( EXISTS ( SELECT 1 FROM BOK_VAL_SCHEME_DETAIL_SPECIAL WHERE VALUATION_PRICE = 'MOD' AND FINPROD_ID = A.FINPROD_ID ) OR EXISTS ( SELECT 1 FROM BOK_VAL_SCHEME_DETAIL F WHERE VALUATION_PRICE = 'MOD' AND D.TYPE_18 = F.SEC_TYPE AND (D.TYPE_1 = F.SEC_DETAIL_TYPE OR F.SEC_DETAIL_TYPE IS NULL) ) )
AND A.FINPROD_ID IN(
#{item}
)
AND A.VDATE <= #{searchDate,jdbcType=DATE}/**起息日**/ AND A.MDATE >= #{searchDate,jdbcType=DATE}/**到期日**/

SELECT A.FINPROD_ID FINPROD_ID,/**金融产品代码**/ A.FINPROD_ABBR FINPROD_ABBR,/**金融产品简称**/ A.FINPROD_MARKET_ID FINPROD_MARKET_ID,/**市场代码**/ A.VDATE VDATE,/**起息日**/ A.MDATE MDATE,/**到期日**/ C.CON_FINPROD_ID CON_FINPROD_ID,/**正股代码**/ C.CON_VDATE CON_VDATE,/**转股起息日**/ C.CON_PRICE CON_PRICE,/**转股价格**/ A.ISSUE_PRICE ISSUE_PRICE,/**发行价**/ D.TYPE_18 AS SEC_TYPE,/**证券品种**/ D.TYPE_1 AS SEC_TYPE_DETAIL /**证券细分类**/ FROM FIN_PRODUCT A /**标的类金融产品表**/ LEFT JOIN FIN_PRODUCT_CONVERTIBLE C ON A.FINPROD_ID = C.FINPROD_ID/**转股信息表**/ INNER JOIN FIN_PRODUCT_TYPE D ON A.FINPROD_ID = D.FINPROD_ID/**金融产品分类表**/ WHERE 1 = 1 AND D.TYPE_18 = '01' AND (D.TYPE_1 = '028' OR D.TYPE_1 = '029')/**可转债、可交换债**/ AND ( EXISTS ( SELECT 1 FROM BOK_VAL_SCHEME_DETAIL_SPECIAL WHERE VALUATION_PRICE = 'MOD' AND FINPROD_ID = A.FINPROD_ID ) OR EXISTS ( SELECT 1 FROM BOK_VAL_SCHEME_DETAIL F WHERE VALUATION_PRICE = 'MOD' AND D.TYPE_18 = F.SEC_TYPE AND (D.TYPE_1 = F.SEC_DETAIL_TYPE OR F.SEC_DETAIL_TYPE IS NULL) ) )
AND A.FINPROD_ID IN(
#{item}
)
AND A.VDATE <= #{searchDate,jdbcType=DATE}/**起息日**/ AND A.MDATE >= #{searchDate,jdbcType=DATE}/**到期日**/

SELECT A.FINPROD_ID FINPROD_ID,/**金融产品代码**/ A.FINPROD_ABBR FINPROD_ABBR,/**金融产品简称**/ A.FINPROD_MARKET_ID FINPROD_MARKET_ID,/**市场代码**/ A.VDATE VDATE,/**起息日**/ A.MDATE MDATE,/**到期日**/ A.ISSUE_PRICE ISSUE_PRICE,/**发行价**/ D.TYPE_18 AS SEC_TYPE,/**证券品种**/ D.TYPE_1 AS SEC_TYPE_DETAIL /**证券细分类**/ FROM FIN_PRODUCT A /**标的类金融产品表**/ INNER JOIN FIN_PRODUCT_TYPE D ON A.FINPROD_ID = D.FINPROD_ID/**金融产品分类表**/ WHERE 1 = 1 AND ( ( D.TYPE_18 = '01' AND ( (D.TYPE_1 != '028' AND D.TYPE_1 != '029')/**可转债、可交换债**/ OR (A.IS_SUS = '01' AND A.IS_RIGHT = '01')/**包含永续含权债**/ ) ) OR D.TYPE_18 = '13' /**其他债权类资产**/ ) AND ( EXISTS ( SELECT 1 FROM BOK_VAL_SCHEME_DETAIL_SPECIAL WHERE VALUATION_PRICE = 'MOD' AND FINPROD_ID = A.FINPROD_ID ) OR EXISTS ( SELECT 1 FROM BOK_VAL_SCHEME_DETAIL F WHERE VALUATION_PRICE = 'MOD' AND D.TYPE_18 = F.SEC_TYPE AND (D.TYPE_1 = F.SEC_DETAIL_TYPE OR F.SEC_DETAIL_TYPE IS NULL) ) )
AND A.FINPROD_ID IN(
#{item}
)
AND A.VDATE <= #{searchDate,jdbcType=DATE}/**起息日**/ AND A.MDATE >= #{searchDate,jdbcType=DATE}/**到期日**/

SELECT A.FINPROD_ID FINPROD_ID, A.FINPROD_ABBR FINPROD_ABBR, A.FINPROD_MARKET_ID FINPROD_MARKET_ID, A.VDATE VDATE, A.MDATE MDATE, A.ISSUER ISSUER, A.FINANCIER FINANCIER, A.SPONSOR SPONSOR, A.IS_SUS IS_SUS, A.IS_RIGHT IS_RIGHT, A.CON_FINPROD_ID CON_FINPROD_ID, A.CON_VDATE CON_VDATE, A.CON_PRICE CON_PRICE, A.COUPON_SPECIES COUPON_SPECIES, A.ACTUAL_CREDIT_PROVID ACTUAL_CREDIT_PROVID, A.ASSET_ONE ASSET_ONE, A.ASSET_TWO ASSET_TWO, A.ASSET_THREE ASSET_THREE, A.ASSET_FOUR ASSET_FOUR, A.ASSET_FIVE ASSET_FIVE, A.ISSUER_FIN_LICENCE ISSUER_FIN_LICENCE, A.FINANCIER_FIN_LICENCE FINANCIER_FIN_LICENCE, A.SPONSOR_FIN_LICENCE SPONSOR_FIN_LICENCE, A.ACTUAL_CREDIT_FIN_LICENCE ACTUAL_CREDIT_FIN_LICENCE, A.ISSUE_AMT ISSUE_AMT, A.COUPON_SPECIES COUPON_SPECIES, A.ISSUE_PRICE ISSUE_PRICE FROM VW_MOD_ASSET_INFO A WHERE EXISTS (SELECT 1 FROM (select A.FINPROD_ID, A.CDATE, A.INV_AIM, SUM(A.AMOUNT) AMOUNT from PTL_SEC_POSITION A INNER JOIN PTL_PORTFOLIO C ON A.PORTFOLIO_ID = C.PORTFOLIO_ID AND C.INVEST_YESORNO = 'Y' INNER JOIN FIN_PRODUCT B ON A.FINPROD_ID = B.FINPROD_ID AND B.FINPROD_TYPE2 IN ('F01', 'F18') where A.HODING_TYPE = '03' GROUP BY A.FINPROD_ID, A.CDATE, A.INV_AIM)M WHERE A.FINPROD_ID = M.FINPROD_ID AND M.INV_AIM = 'AC' AND M.AMOUNT > 0)
AND A.FINPROD_ID IN(
#{item}
)
AND A.ASSET_FIVE IN(
#{item}
)

SELECT A.CON_FINPROD_ID CON_FINPROD_ID, A.FINPROD_MARKET_ID FINPROD_MARKET_ID, A.DEAL_DATE DEAL_DATE, A.CLOSE_PRICE CLOSE_PRICE, A.PB PB, A.PE PE FROM FIN_PRODUCT A INNER JOIN MST_SHARE_PRICE B ON A.FINPROD_MARKET_ID = B.SHARES_ID where 1=1
AND A.FINPROD_ID IN(
#{item}
)
AND B.DEAL_DATE >= #{startDate, jdbcType=DATE}
and B.DEAL_DATE <= #{searchDate, jdbcType=DATE}
ORDER BY B.DEAL_DATE

SELECT A.CURVE_DATE CURVE_DATE, A.CURVE_CODE CURVE_CODE, A.KEY_POINT KEY_POINT, A.YIELD YIELD, A.CURVE_TYPE CURVE_TYPE FROM MST_YIELD_CURVE_INFO A where 1=1
AND A.CURVE_CODE IN(
#{item}
)
AND A.CURVE_DATE >= #{startDate, jdbcType=DATE}
and A.CURVE_DATE <= #{searchDate, jdbcType=DATE}
ORDER BY A.CURVE_DATE,A.KEY_POINT

select * from ( SELECT A.OCODE OCODE, A.OTYPE OTYPE, A.GRADEORGID GRADEORGID, A.GRADEDATE GRADEDATE, A.MSTRATINGRESULT01 GRADERESULT FROM (SELECT A.OCODE AS OCODE, A.OTYPE AS OTYPE, A.INNEROUTER AS INNEROUTER, A.GRADEORGID AS GRADEORGID, A.GRADEDATE AS GRADEDATE, A.NOTICEDATE AS NOTICEDATE, A.SHORTLONGTERM AS SHORTLONGTERM, A.MSTRATINGRESULT01 AS MSTRATINGRESULT01, A.MSTRATINGRESULT02 AS MSTRATINGRESULT02, A.INPUTTYPE AS INPUTTYPE, A.GRADEEXPECTATION AS GRADEEXPECTATION, A.DIRECTIONCHANGE AS DIRECTIONCHANGE, A.ISSUERRATETYPE AS ISSUERRATETYPE FROM ( SELECT MBCR.O_CODE AS OCODE, MBCR.O_TYPE AS OTYPE, '01' AS INNEROUTER, MBCR.GRADE_ORG_ID AS GRADEORGID, MBCR.GRADE_DATE AS GRADEDATE, MBCR.NOTICE_DATE AS NOTICEDATE, MBCR.SHORT_LONG_TERM AS SHORTLONGTERM, MBCR.GRADE_RESULT AS MSTRATINGRESULT01, MRM.GRADE_RESULT_ST AS MSTRATINGRESULT02, MBCR.INPUT_TYPE AS INPUTTYPE, MBCR.GRADE_EXPECTATION AS GRADEEXPECTATION, MBCR.DIRECTION_CHANGE AS DIRECTIONCHANGE, MBCR.ISSUER_RATE_TYPE AS ISSUERRATETYPE FROM MST_BOND_CREDIT_RATING MBCR LEFT JOIN MST_RATING_MATCH MRM ON MBCR.GRADE_RESULT = MRM.GRADE_RESULT_OR UNION ALL SELECT MICR.O_CODE AS OCODE, MICR.O_TYPE AS OTYPE, '02' AS INNEROUTER, MICR.GRADE_ORG_ID AS GRADEORGID, MICR.GRADE_DATE AS GRADEDATE, NULL AS NOTICEDATE, NULL AS SHORTLONGTERM, MICR.GRADE_RESULT AS MSTRATINGRESULT01, MRM1.GRADE_RESULT_ST AS MSTRATINGRESULT02, MICR.INPUT_TYPE AS INPUTTYPE, NULL AS GRADEEXPECTATION, NULL AS DIRECTIONCHANGE, NULL AS ISSUERRATETYPE FROM MST_INNER_CREDIT_RATING MICR LEFT JOIN MST_RATING_MATCH MRM1 ON MICR.GRADE_RESULT = MRM1.GRADE_RESULT_OR) A)A WHERE 1=1
AND A.OCODE = #{ocode,jdbcType=VARCHAR}
AND A.OTYPE = #{otype,jdbcType=VARCHAR}
AND A.GRADEORGID = '98'
AND A.GRADEORGID != '98'
AND A.GRADEDATE <= #{gradedate, jdbcType=DATE}
ORDER BY A.GRADEDATE DESC) where ROWNUM =1

select * from ( SELECT A.OCODE OCODE, A.OTYPE OTYPE, A.GRADEORGID GRADEORGID, A.GRADEDATE GRADEDATE, A.MSTRATINGRESULT01 GRADERESULT FROM (SELECT A.OCODE AS OCODE, A.OTYPE AS OTYPE, A.INNEROUTER AS INNEROUTER, A.GRADEORGID AS GRADEORGID, A.GRADEDATE AS GRADEDATE, A.NOTICEDATE AS NOTICEDATE, A.SHORTLONGTERM AS SHORTLONGTERM, A.MSTRATINGRESULT01 AS MSTRATINGRESULT01, A.MSTRATINGRESULT02 AS MSTRATINGRESULT02, A.INPUTTYPE AS INPUTTYPE, A.GRADEEXPECTATION AS GRADEEXPECTATION, A.DIRECTIONCHANGE AS DIRECTIONCHANGE, A.ISSUERRATETYPE AS ISSUERRATETYPE FROM ( SELECT MBCR.O_CODE AS OCODE, MBCR.O_TYPE AS OTYPE, '01' AS INNEROUTER, MBCR.GRADE_ORG_ID AS GRADEORGID, MBCR.GRADE_DATE AS GRADEDATE, MBCR.NOTICE_DATE AS NOTICEDATE, MBCR.SHORT_LONG_TERM AS SHORTLONGTERM, MBCR.GRADE_RESULT AS MSTRATINGRESULT01, MRM.GRADE_RESULT_ST AS MSTRATINGRESULT02, MBCR.INPUT_TYPE AS INPUTTYPE, MBCR.GRADE_EXPECTATION AS GRADEEXPECTATION, MBCR.DIRECTION_CHANGE AS DIRECTIONCHANGE, MBCR.ISSUER_RATE_TYPE AS ISSUERRATETYPE FROM MST_BOND_CREDIT_RATING MBCR LEFT JOIN MST_RATING_MATCH MRM ON MBCR.GRADE_RESULT = MRM.GRADE_RESULT_OR UNION ALL SELECT MICR.O_CODE AS OCODE, MICR.O_TYPE AS OTYPE, '02' AS INNEROUTER, MICR.GRADE_ORG_ID AS GRADEORGID, MICR.GRADE_DATE AS GRADEDATE, NULL AS NOTICEDATE, NULL AS SHORTLONGTERM, MICR.GRADE_RESULT AS MSTRATINGRESULT01, MRM1.GRADE_RESULT_ST AS MSTRATINGRESULT02, MICR.INPUT_TYPE AS INPUTTYPE, NULL AS GRADEEXPECTATION, NULL AS DIRECTIONCHANGE, NULL AS ISSUERRATETYPE FROM MST_INNER_CREDIT_RATING MICR LEFT JOIN MST_RATING_MATCH MRM1 ON MICR.GRADE_RESULT = MRM1.GRADE_RESULT_OR) A)A WHERE 1=1
AND A.OCODE IN(
#{item}
)
AND A.OTYPE = '01' AND A.GRADEORGID = #{gradeorgId,jdbcType=VARCHAR} AND A.GRADEDATE <= #{searchDate, jdbcType=DATE} ORDER BY A.GRADEDATE DESC) where ROWNUM =1
